// upstreamParseError renders the inner reason of a url.Parse failure against
// raw without ever echoing the address: url.Parse wraps its errors as
// parse "<full URL>": <detail>, and quoting the error verbatim would write
// the configured username and password into the failure reason even when
// the parse failure itself is only a malformed escape in the base path.
// The quoted URL is therefore dropped and only the detail is kept; the
// route position, id and upstream field are named by the caller, and the
// detail is text url.Parse derives from a single offending token (a bad
// escape, a bad host character, the bad port) and never from the userinfo,
// which parseAuthority checks with a fixed "net/url: invalid userinfo"
// string. redactUpstream is applied anyway as a belt-and-braces guard, so a
// future parser version cannot start quoting authority bytes here.
func upstreamParseError(raw string, err error) string {
	var uerr *url.Error
	detail := err.Error()
	if errors.As(err, &uerr) {
		detail = uerr.Err.Error()
	}
	return redactUpstream(detail)
}

