			name:      "missing closing bracket after userinfo",
			upstream:  "http://alice:secret@[::1/base",
			wantQuote: "missing ']' in host",
			cause:     []string{"upstream is not a valid URL"},
			leaks:     []string{"alice", "secret", `parse "`},
		},
