			wantQuote: "https://***@:8443/v1",
			cause:     []string{"missing a host"},
			leaks:     []string{"p%40ss", "p@ss", "user:"},
		},
		{
			name:      "plain password before a bare port",
			upstream:  "http://alice:s3cret@:8080/base",
			wantQuote: "http://***@:8080/base",
			cause:     []string{"missing a host"},
