// upstreamParseError renders the inner reason of a url.Parse failure without
// ever echoing the address: url.Parse wraps its errors as
// parse "<full URL>": <detail>, and quoting the error verbatim would write
// the configured username and password into the failure reason even when
// the parse failure itself is only a malformed escape in the base path.
// The quoted URL is therefore dropped and only the detail is kept; the
// route position, id and upstream field are named by the caller. The detail
// is text url.Parse derives from a single offending token — a bad escape
// (EscapeError), a bad host character (InvalidHostError), the bad port
// ("invalid port %q") or one of a set of fixed strings ("missing ']' in
// host", "net/url: invalid userinfo", ...) — and never quotes userinfo
// bytes, which parseAuthority validates with a fixed message. The detail is
// passed through redactUpstream anyway as a belt-and-braces guard, so a
// future parser version that started quoting a full address inside the
// detail could not leak credentials here.
func upstreamParseError(err error) string {
	var uerr *url.Error
	detail := err.Error()
	if errors.As(err, &uerr) {
		detail = uerr.Err.Error()
	}
	return redactUpstream(detail)
}

